memberdef.initializer:
= {
    {16, Align::Constant<2>(), Align::Constant<2>()},    
    {32, Align::Constant<4>(), Align::Constant<4>()},    
    {64, Align::Constant<8>(), Align::Constant<8>()},    
    {128, Align::Constant<16>(), Align::Constant<16>()}, 
